function navName(){var n=navSet().find(function(x){return x[0]===state.page;});return n?n[1]:'Genel Bakış';}
function switchRole(r){state.role=r;state.page=r==='admin'?'overview':r==='resident'?'resident':'field';state.tab='all';state.query='';save('role',r);save('page',state.page);render();}
