function badge(txt){var cls=/Ödendi|Okundu|Tamamlandı|Onaylı|İşlendi/.test(txt)?'ok':/Gecikti|Anomali|Acil|Bağlantı yok/.test(txt)?'danger':/Bekle|Yeni|Atandı/.test(txt)?'warn':'info';return '<span class="pill '+cls+'">'+esc(txt)+'</span>';}
