function title(over,head,sub,actions){return '<div class="page-title"><div><div class="eyebrow">'+over+'</div><h1>'+head+'</h1><p class="subtitle">'+sub+'</p></div><div class="header-actions">'+(actions||'')+'</div></div>';}
function metric(lbl,num,note,ic,trend){return '<div class="card metric"><div class="metric-top">'+esc(lbl)+'<div class="metric-icon">'+icon(ic||'chart',15)+'</div></div><div class="metric-val">'+num+'</div><div class="metric-bottom">'+(trend?'<span class="trend '+(trend.indexOf('-')===0?'bad':'')+'">'+esc(trend)+'</span>':'')+esc(note)+'</div></div>';}
function chartSVG(series){var paid=series||[56,68,61,79,83,92],expense=[43,48,51,58,53,65],months=paid.length===12?['Ara','Oca','Şub','Mar','Nis','May','Haz','Tem','Ağu','Eyl','Eki','Kas']:['Haz','Tem','Ağu','Eyl','Eki','Kas'];var count=paid.length,step=600/(count-1);var p=paid.map(function(n,i){return [28+i*step,184-(n*1.65)];});var e=expense.map(function(n,i){return [28+i*step,184-(n*1.65)];});function path(points){return points.map(function(v,i){return (i?'L':'M')+v[0]+','+v[1];}).join(' ');}var area=path(p)+' L'+p[p.length-1][0]+',184 L28,184 Z';var grid=[25,65,105,145,184].map(function(y){return '<line class="chart-gridline" x1="28" y1="'+y+'" x2="628" y2="'+y+'"/>';}).join('');var labels=months.map(function(m,i){return '<text class="chart-label" x="'+(28+i*step)+'" y="206" text-anchor="middle">'+m+'</text>';}).join('');var dots=p.map(function(v){return '<circle cx="'+v[0]+'" cy="'+v[1]+'" r="3.8" fill="white" stroke="#126bc8" stroke-width="2.4"/>';}).join('');return '<div class="chart-wrap"><svg viewBox="0 0 650 222" role="img" aria-label="Temsilî aidat tahsilat ve gider grafiği"><defs><linearGradient id="garea" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#77aef1" stop-opacity=".27"/><stop offset="1" stop-color="#77aef1" stop-opacity="0"/></linearGradient></defs>'+grid+'<path d="'+area+'" fill="url(#garea)"/><path d="'+path(e)+'" fill="none" stroke="#a7c5e6" stroke-width="2.4" stroke-dasharray="4 6"/><path d="'+path(p)+'" fill="none" stroke="#126bc8" stroke-width="3.7" stroke-linecap="round" stroke-linejoin="round"/>'+dots+labels+'</svg></div><div class="legend"><span><b></b> Tahsilat</span><span class="l2"><b></b> Giderler</span><span style="margin-left:auto;color:#a0aebc">Örnek veriler</span></div>';}
function quick(label,desc,ic,action){return '<button type="button" class="quick-item" data-action="'+action+'"><span class="quick-icon">'+icon(ic,16)+'</span><span class="quick-title"><strong>'+label+'</strong><small>'+desc+'</small></span>'+icon('chevron',14)+'</button>';}
